from robot.utils.robottime import timestr_to_secs
from robot.api import logger

from .base import BaseInterface
from ..util import wrap_result
from ..validators import ObjectValidator, Or, IsString, InRange, IsOneOf
from ..converter import to_bool, to_int


class TestModelInterface(BaseInterface):

    def reset_to_test_dedicated(self, timeout=300, alias="default"):
        """Preform radio reset procedure.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("resetToTestDedicated", {}, timeout)

    def start_uplink_test(self, dist_name, test_model, interval, offset, earfcn, tdd_frame_conf=None,
                          tdd_spec_subf_conf=None, timeout=60, alias="default"):
        """Start LTE uplink test.

        :param string dist_name: LNCEL_R object to perform test on
        :param string test_model: Test model type.
        :param integer interval: Reporting time interval [0..4294967295]
        :param integer offset: Resource block offset [0..75]
        :param integer earfcn: earfcn [0..65535].
        :param integer tdd_frame_conf: TDD frame configuration
        :param integer tdd_spec_subf_conf: TDD subframe configuration
        :param string alias: Name of execution context
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context
        """

        interval = to_int(interval)
        offset = to_int(offset)
        earfcn = to_int(earfcn)
        timeout = timestr_to_secs(timeout)

        IsString().check(dist_name)
        IsString().check(test_model)
        InRange(0, 4294967295).check(interval)
        InRange(0, 99).check(offset)
        InRange(0, 262143).check(earfcn)

        parameters = {
            "lncel_rDN": dist_name,
            "params": {
                "referenceChannelNumber": test_model,
                "reportingTimeInterval": interval,
                "resourceBlockOffset": offset,
                "earfcn": earfcn
            }
        }

        if tdd_frame_conf and tdd_spec_subf_conf:
            tdd_frame_conf = to_int(tdd_frame_conf)
            tdd_spec_subf_conf = to_int(tdd_spec_subf_conf)

            InRange(1, 3).check(tdd_frame_conf)
            InRange(3, 9).check(tdd_spec_subf_conf)

            parameters["params"]["tddFrameConf"] = tdd_frame_conf
            parameters["params"]["tddSpecSubfConf"] = tdd_spec_subf_conf

        elif bool(tdd_frame_conf) != bool(tdd_spec_subf_conf):
            logger.warn("tddFrameConf and tddSpecSubfConf parameters have to be set both at a time")

        self.store.get(alias).execute_procedure("startLteUplinkTest", parameters, timeout)

    def start_downlink_test(self, dist_name, test_model, earfcn, phy_cell_id=None, tdd_frame_conf=None,
                            tdd_spec_subf_conf=None, timeout=60, alias="default"):
        """Start LTE downlink test.

        :param string dist_name: LNCEL_R object to perform test on
        :param string test_model: Test model type.
        :param integer earfcn: earfcn [0..65535] MHz.
        :param integer phy_cell_id: Physical cell ID (optional)
        :param integer tdd_frame_conf: TDD frame configuration (optional)
        :param integer tdd_spec_subf_conf: TDD subframe configuration (optional)
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        earfcn = to_int(earfcn)

        IsString().check(dist_name)
        IsString().check(test_model)
        InRange(0, 262143).check(earfcn)

        parameters = {
            "lncel_rDN": dist_name,
            "params": {
                "testModel": test_model,
                "earfcn": earfcn
            }
        }

        if phy_cell_id is not None:
            phy_cell_id = to_int(phy_cell_id)
            parameters["params"]["phyCellId"] = phy_cell_id

        if tdd_frame_conf and tdd_spec_subf_conf:
            tdd_frame_conf = to_int(tdd_frame_conf)
            tdd_spec_subf_conf = to_int(tdd_spec_subf_conf)

            InRange(1, 3).check(tdd_frame_conf)
            InRange(3, 9).check(tdd_spec_subf_conf)

            parameters["params"]["tddFrameConf"] = tdd_frame_conf
            parameters["params"]["tddSpecSubfConf"] = tdd_spec_subf_conf

        elif bool(tdd_frame_conf) != bool(tdd_spec_subf_conf):
            logger.warn("tddFrameConf and tddSpecSubfConf parameters have to be set both at a time")

        self.store.get(alias).execute_procedure("startLteDownlinkTest", parameters, timeout)

    def assert_uplink_test_results(self, dist_name, parameters=None, timeout=60, alias="default"):
        """Watch LTE uplink test results.

        :param string dist_name: Target dist name.
        :param string parameters: Requierd test result parameters.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        Or(IsString(), IsOneOf(None)).check(parameters)

        self.store.get(alias).execute_procedure_subscription(
            "watchLteUplinkTestResults", {"lncel_rDN": dist_name}, ObjectValidator(parameters), timeout)

    def stop_uplink_test(self, dist_name, timeout=60, alias="default"):
        """Stop LTE uplink test.

        :param string dist_name: Target dist name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        self.store.get(alias).execute_procedure("stopLteUplinkTest", {"lncel_rDN": dist_name}, timeout)

    def stop_downlink_test(self, dist_name, timeout=60, alias="default"):
        """Stop LTE downlink test.

        :param string dist_name: Target dist name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        self.store.get(alias).execute_procedure("stopLteDownlinkTest", {"lncel_rDN": dist_name}, timeout)

    @wrap_result
    def get_active_tests(self, timeout=60, alias="default"):
        """Get active tests.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of active test models
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("getActiveTest", {}, timeout)

    def start_wcdma_uplink_test(self, dist_name, uarfcn, uplink_scrambling_code, in_sync_limit=None, out_sync_limit=None,
                                auto_report=None, timeout=60, alias="default"):
        """Start WCDMA uplink test.

        :param string dist_name: WNCEL_R object to perform test on
        :param integer uarfcn: earfcn [0..4294967295].
        :param integer uplink_scrambling_code: uplinkScramblingCode [0..16777215].
        :param integer in_sync_limit: inSyncLimit [0..4294967295] optional parameter.
        :param integer out_sync_limit: outSyncLimit [0..4294967295] optional parameter.
        :param boolean auto_report: autoReport - optional parameter.
        :param float timeout: Time in seconds to wait for positive procedure result
        :param string alias: Name of execution context
        """

        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        uarfcn = to_int(uarfcn)
        InRange(0, 4294967295).check(uarfcn)
        uplink_scrambling_code = to_int(uplink_scrambling_code)
        InRange(0, 16777215).check(uplink_scrambling_code)

        parameters = {
            "wncel_rDN": dist_name,
            "params": {
                "uarfcn": uarfcn,
                "uplinkScramblingCode": uplink_scrambling_code
            }
        }

        if in_sync_limit is not None:
            in_sync_limit = to_int(in_sync_limit)
            InRange(0, 4294967295).check(uarfcn)
            parameters["params"]["inSyncLimit"] = in_sync_limit

        if out_sync_limit is not None:
            out_sync_limit = to_int(out_sync_limit)
            InRange(0, 4294967295).check(out_sync_limit)
            parameters["params"]["outSyncLimit"] = out_sync_limit

        if auto_report is not None:
            auto_report = to_bool(auto_report)
            parameters["params"]["autoReport"] = auto_report

        self.store.get(alias).execute_procedure("startWcdmaUplinkTest", parameters, timeout)

    def stop_wcdma_uplink_test(self, dist_name, timeout=60, alias="default"):
        """Stop WCDMA uplink test.

        :param string dist_name: Target WNCEL_R-n dist name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
                """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        self.store.get(alias).execute_procedure("stopWcdmaUplinkTest", {"wncel_rDN": dist_name}, timeout)

    def start_wcdma_downlink_test(self, dist_name, uarfcn, test_model, primary_scrambling_code, number_of_dpch, number_of_hs_pdsch=None,  # noqa C901
                                  primary_ccpch_tx_power=None, dpch_tx_power=None, dpch_tx_pwr_ctrl_step_size=None, mimo_phase=None,
                                  mimo_stream=None, vam_dedicated_test_model=None, timeout=60, alias="default"):
        """Start WCDMA downlink test.

        :param string dist_name: WNCEL_R object to perform test on
        :param integer uarfcn: earfcn [0..4294967295]
        :param string test_model: (TM_1, TM_2, TM_3, TM_4, TM_5, TM_6, TM_N7, TM_N8, TM_N9, TM_N10, TM_N11, TM_N12, TM_N13).
        :param integer primary_scrambling_code: primaryScramblingCode [0..511]
        :param integer number_of_dpch: numberOfDpch [0..64]
        :param integer number_of_hs_pdsch: numberOfHsPdsch [0..8 multiple of 2] - optional parameter.
        :param integer primary_ccpch_tx_power: primaryCcpchTxPower [-26..-6] - optional parameter.
        :param integer dpch_tx_power: dpchTxPower [-28..-3] - optional parameter.
        :param string dpch_tx_pwr_ctrl_step_size: dpchTxPwrCtrlStepSize: (0_0, 0_5, 1_0, 1_5, 2_0) - optional parameter.
        :param string mimo_phase: mimoPhase: (Zero, One, Two, Three, NoMimo) - optional parameter.
        :param string mimo_stream: mimoStream: (Single" | "Dual) - optional parameter.
        :param boolean vam_dedicated_test_model: vamDedicatedTestModel - optional parameter.
        :param float timeout: Time in seconds to wait for positive procedure result
        :param string alias: Name of execution context
        """

        IsString().check(dist_name)
        timeout = timestr_to_secs(timeout)
        uarfcn = to_int(uarfcn)
        InRange(0, 4294967295).check(uarfcn)
        IsString().check(test_model)
        test_model = test_model.upper()
        IsOneOf("TM_1", "TM_2", "TM_3", "TM_4", "TM_5", "TM_6", "TM_N7",
                "TM_N8", "TM_N9", "TM_N10", "TM_N11", "TM_N12", "TM_N13").check(test_model)
        primary_scrambling_code = to_int(primary_scrambling_code)
        InRange(0, 511).check(primary_scrambling_code)
        number_of_dpch = to_int(number_of_dpch)
        InRange(0, 64).check(number_of_dpch)

        parameters = {
            "wncel_rDN": dist_name,
            "params": {
                "uarfcn": uarfcn,
                "testModel": test_model,
                "primaryScramblingCode": primary_scrambling_code,
                "numberOfDpch": number_of_dpch
            }
        }

        if number_of_hs_pdsch is not None:
            number_of_hs_pdsch = to_int(number_of_hs_pdsch)
            IsOneOf(0, 2, 4, 6, 8).check(number_of_hs_pdsch)
            parameters["params"]["numberOfHsPdsch"] = number_of_hs_pdsch

        if primary_ccpch_tx_power is not None:
            primary_ccpch_tx_power = to_int(primary_ccpch_tx_power)
            InRange(-26, -6).check(primary_ccpch_tx_power)
            parameters["params"]["primaryCcpchTxPower"] = primary_ccpch_tx_power

        if dpch_tx_power is not None:
            dpch_tx_power = to_int(dpch_tx_power)
            InRange(-28, -3).check(dpch_tx_power)
            parameters["params"]["dpchTxPower"] = dpch_tx_power

        if dpch_tx_pwr_ctrl_step_size is not None:
            IsString().check(dpch_tx_pwr_ctrl_step_size)
            IsOneOf("0_0", "0_5", "1_0", "1_5", "2_0").check(dpch_tx_pwr_ctrl_step_size)
            parameters["params"]["dpchTxPwrCtrlStepSize"] = dpch_tx_pwr_ctrl_step_size

        if mimo_phase is not None:
            IsString().check(mimo_phase)
            IsOneOf("Zero", "One", "Two", "Three", "NoMimo").check(mimo_phase)
            parameters["params"]["mimoPhase"] = mimo_phase

        if mimo_stream is not None:
            IsString().check(mimo_stream)
            mimo_stream = mimo_stream.title()
            IsOneOf("Single", "Dual").check(mimo_stream)
            parameters["params"]["mimoStream"] = mimo_stream

        if vam_dedicated_test_model is not None:
            vam_dedicated_test_model = to_bool(vam_dedicated_test_model)
            parameters["params"]["vamDedicatedTestModel"] = vam_dedicated_test_model

        self.store.get(alias).execute_procedure("srtStartWcdmaDownlink", parameters, timeout)

    def stop_wcdma_downlink_test(self, dist_name, timeout=60, alias="default"):
        """Stop WCDMA downlink test.

        :param string dist_name: Target WNCEL_R-n dist name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
                """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        self.store.get(alias).execute_procedure("srtStopWcdmaDownlinkTest", {"wncel_rDN": dist_name}, timeout)

    def watch_periodic_results(self, dist_name, watch_time=60, finalizer_timeout=10, alias="default"):
        """Watch periodic test results.

        :param string dist_name: Target WNCEL_R-n or TRX-n dist name.
        :param float watch_time: Time for collecting results.
        :param float finalizer_timeout: Time for finalizing.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: last watch Periodic Result
                """
        watch_time = timestr_to_secs(watch_time)
        finalizer_timeout = timestr_to_secs(finalizer_timeout)
        IsString().check(dist_name)

        response = self.store.get(alias).execute_endless_procedure("watchPeriodicResults",
                                                                   {"target_rDN": dist_name},
                                                                   watch_time,
                                                                   finalizer_timeout)
        return self.store.get(alias).check_if_response_status_is_expected(response, "update").get_payload()
